import{_ as i,o as a,c as e,l as s,t as o,N as n}from"./chunks/framework.Bbd9fWQx.js";const f=JSON.parse('{"title":"git-diagnose | x-cmd man (git man1) | Generate a zip archive of diagnostic information","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-diagnose - Generate a zip archive of diagnostic information","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-diagnose | x-cmd man (git man1) | Generate a zip archive of diagnostic information"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-diagnose - Generate a zip archive of diagnostic information"}]]},"headers":[],"params":{"isMan":true,"man":"git-diagnose","category":"git man1","desc":"Generate a zip archive of diagnostic information"},"relativePath":"git/man1/git-diagnose.md","filePath":"git/man1/git-diagnose.md"}'),r={name:"git/man1/git-diagnose.md"},l={class:"visually-hidden"},h=n(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-diagnose - Generate a zip archive of diagnostic information</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diagnose</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [(-o </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> --output-directory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">path</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] [(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">s </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">suffix) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">format</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   [--mode</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mode</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Collects detailed information about the user&#39;s machine, Git client, and repository state and packages that information into a zip archive. The generated archive can then, for example, be shared with the Git mailing list to help debug an issue or serve as a reference for independent debugging.</p><p>By default, the following information is captured in the archive:</p><blockquote><p>·</p><p><em>git version --build-options</em></p></blockquote><blockquote><p>·</p><p>The path to the repository root</p></blockquote><blockquote><p>·</p><p>The available disk space on the filesystem</p></blockquote><blockquote><p>·</p><p>The name and size of each packfile, including those in alternate object stores</p></blockquote><blockquote><p>·</p><p>The total count of loose objects, as well as counts broken down by <strong>.git/objects</strong> subdirectory</p></blockquote><p>Additional information can be collected by selecting a different diagnostic mode using the <strong>--mode</strong> option.</p><p>This tool differs from <strong>git-bugreport</strong>(1) in that it collects much more detailed information with a greater focus on reporting the size and data shape of repository contents.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>-o &lt;path&gt;, --output-directory &lt;path&gt;</p><blockquote><p>Place the resulting diagnostics archive in <strong>&lt;path&gt;</strong> instead of the current directory.</p></blockquote><p>-s &lt;format&gt;, --suffix &lt;format&gt;</p><blockquote><p>Specify an alternate suffix for the diagnostics archive name, to create a file named <em>git-diagnostics-&lt;formatted suffix&gt;</em>. This should take the form of a strftime(3) format string; the current local time will be used.</p></blockquote><p>--mode=(stats|all)</p><blockquote><p>Specify the type of diagnostics that should be collected. The default behavior of <em>git diagnose</em> is equivalent to <strong>--mode=stats</strong>.</p><p>The <strong>--mode=all</strong> option collects everything included in <strong>--mode=stats</strong>, as well as copies of <strong>.git</strong>, <strong>.git/hooks</strong>, <strong>.git/info</strong>, <strong>.git/logs</strong>, and <strong>.git/objects/info</strong> directories. This additional information may be sensitive, as it can be used to reconstruct the full contents of the diagnosed repository. Users should exercise caution when sharing an archive generated with <strong>--mode=all</strong>.</p></blockquote><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,23);function p(t,d,g,c,k,m){return a(),e("div",null,[s("h1",l,o(t.$params.man),1),h])}const b=i(r,[["render",p]]);export{f as __pageData,b as default};
